import org.springframework.data.repository.query.parser.Part;
import org.springframework.data.repository.query.parser.PartTree;

// Spring Data が派生クエリのメソッド名を解析するクラス PartTree を、直接呼んでみる
class Department { Long id; String name; }
class Employee { Long id; String name; int age; Department department; }

// ここを変えてみよう:メソッド名を書き換えて再実行
// (Or を入れる・Asc にする・First にする・わざと nmae とつづりを間違える など)
String[] names = {
    "findByNameAndAge",
    "findTop3ByDepartmentNameOrderByAgeDesc",
    "countByAgeBetween",
    "findByNameContainingOrAgeLessThan",
    "findByNmae",
};

for (String name : names) {
    System.out.println("■ " + name);
    try {
        PartTree tree = new PartTree(name, Employee.class);
        int group = 1;
        for (PartTree.OrPart or : tree) {      // Or で区切られたグループ
            for (Part p : or) {                // グループ内は And
                System.out.println("  条件" + group + ": "
                        + p.getProperty().toDotPath() + " " + p.getType());
            }
            group++;
        }
        System.out.println("  並び順: " + tree.getSort()
                + " / 件数制限: " + (tree.isLimiting() ? tree.getMaxResults() : "なし")
                + " / count: " + tree.isCountProjection());
    } catch (RuntimeException e) {
        System.out.println("  起動時エラーになる: " + e.getMessage());
    }
}

